/**
 * The five worked-example charts on /scoring/data-cleaning (issue #860 §1).
 *
 * They are static SVG, generated by
 * web/scripts/generate-data-cleaning-charts.ts and checked in. A static SVG
 * scales its type with its width, and a prerendered page cannot measure
 * itself as the React charts do. The charts were a 560-unit drawing with
 * 10-unit labels, so a phone painted the labels at 6.2px. The source said 10.
 *
 * The generator now draws a narrow viewBox with 13-unit labels and caps the
 * figure's width. This spec holds both ends of that: the labels are 11px or
 * more as PAINTED (accessibility standard §7) down to the 320px floor (§3.2),
 * and they do not grow large on a desktop. It measures after the SVG's
 * scaling, because a class or a `font-size` attribute says nothing about the
 * painted size.
 *
 * It runs in both Playwright projects. ssr.spec.ts repeats the measurement
 * against the built output, where Astro and Tailwind have frozen the page.
 */
import { test, expect, type Page } from "./fixtures/test";

const FIGURES = [
  "illustration-cross-check",
  "illustration-real-dive",
  "illustration-sea-level",
  "example-spike",
  "example-dropout",
] as const;

/** The smallest painted label size the standard allows. */
const MIN_PX = 11;
/** The largest a label may be painted, at any width. The figure's cap gives
 * 17.3px; body text on this page is 14px. */
const MAX_PX = 18;

interface FigureReport {
  id: string;
  texts: number;
  /** Painted sizes, smallest and largest. */
  min: number;
  max: number;
  small: string[];
  clipped: string[];
  /** Text beside the SVG: the legend and the caption. */
  smallBeside: string[];
  /** The three series' line styles, as drawn. */
  dashes: string[];
}

/** Every label of every figure, as painted. */
async function measure(page: Page): Promise<FigureReport[]> {
  return page.evaluate(
    ({ ids, minPx }) =>
      ids.map((id) => {
        const fig = document.getElementById(id)!;
        const svg = fig.querySelector<SVGSVGElement>("svg[viewBox]")!;
        const box = svg.getBoundingClientRect();
        const scale = box.width / svg.viewBox.baseVal.width;
        const sizes: number[] = [];
        const small: string[] = [];
        const clipped: string[] = [];
        for (const text of svg.querySelectorAll("text")) {
          const painted = parseFloat(getComputedStyle(text).fontSize) * scale;
          sizes.push(painted);
          const label = `${text.textContent} (${painted.toFixed(1)}px)`;
          if (painted < minPx) small.push(label);
          const r = text.getBoundingClientRect();
          if (
            r.left < box.left - 0.5 ||
            r.right > box.right + 0.5 ||
            r.top < box.top - 0.5 ||
            r.bottom > box.bottom + 0.5
          ) {
            clipped.push(label);
          }
        }
        const smallBeside: string[] = [];
        for (const el of fig.querySelectorAll<HTMLElement>("span, figcaption")) {
          const px = parseFloat(getComputedStyle(el).fontSize);
          if (px < minPx) smallBeside.push(`${el.textContent?.slice(0, 30)} (${px}px)`);
        }
        return {
          id,
          texts: sizes.length,
          min: Math.min(...sizes),
          max: Math.max(...sizes),
          small,
          clipped,
          smallBeside,
          dashes: [...svg.querySelectorAll("path")].map(
            (p) => p.getAttribute("stroke-dasharray") ?? "solid"
          ),
        };
      }),
    { ids: [...FIGURES], minPx: MIN_PX }
  );
}

async function expectReadable(page: Page) {
  const reports = await measure(page);
  expect(reports.map((r) => r.id)).toEqual([...FIGURES]);
  for (const r of reports) {
    // Two y ticks at the least, the unit, three times and the zone.
    expect(r.texts, `${r.id}: labels drawn`).toBeGreaterThanOrEqual(7);
    expect(r.small, `${r.id}: labels painted under ${MIN_PX}px`).toEqual([]);
    expect(r.clipped, `${r.id}: labels that leave the chart`).toEqual([]);
    expect(r.smallBeside, `${r.id}: legend or caption under ${MIN_PX}px`).toEqual([]);
    expect(r.max, `${r.id}: labels must not grow large`).toBeLessThanOrEqual(MAX_PX);
    // The lines carry no labels, so the line style is what tells them apart
    // without colour: three series, three styles.
    expect(new Set(r.dashes).size, `${r.id}: one line style for each series`).toBe(3);
  }
  expect(
    await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth),
    "the page must not scroll sideways"
  ).toBe(true);
}

test.describe("/scoring/data-cleaning: the worked-example charts", () => {
  test("every label is painted at 11px or more, none leaves its chart, and the page does not scroll sideways", async ({
    page,
  }) => {
    await page.goto("/scoring/data-cleaning");
    await expectReadable(page);
  });

  // 393px is the phone issue #860 was measured on, and 320px is the narrowest
  // viewport the accessibility standard supports (§3.2).
  for (const width of [393, 320]) {
    test(`the same at ${width}px wide`, async ({ page }) => {
      await page.setViewportSize({ width, height: 700 });
      await page.goto("/scoring/data-cleaning");
      await expectReadable(page);
    });
  }

  test("the legend names each line and draws it in the chart's own style", async ({ page }) => {
    await page.goto("/scoring/data-cleaning");
    for (const id of FIGURES) {
      const fig = page.locator(`#${id}`);
      for (const name of ["raw GPS altitude", "raw barometric altitude", "cleaned"]) {
        await expect(fig.getByText(name, { exact: true })).toBeVisible();
      }
      // A dotted and a dashed swatch, as the barometer and cleaned lines are.
      const styles = await fig.evaluate((el) =>
        [...el.querySelectorAll<HTMLElement>("div[aria-hidden] > span > span")].map(
          (s) => getComputedStyle(s).borderTopStyle
        )
      );
      expect(styles).toContain("dotted");
      expect(styles).toContain("dashed");
    }
  });

  test.describe("with JavaScript off", () => {
    test.use({ javaScriptEnabled: false });

    test("the charts and their captions are in the page", async ({ page }) => {
      await page.goto("/scoring/data-cleaning");
      for (const id of FIGURES) {
        const fig = page.locator(`#${id}`);
        await expect(fig.locator("svg[role='img']")).toBeVisible();
        await expect(fig.locator("figcaption")).toBeVisible();
      }
    });
  });
});
